/*
 * A183210  Tree generated by 3n-2.
 * https://oeis.org/A183210
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the binary tree with L(x)=3x-2,
 *            U(x)=(3x+1)/2, and read by rows: a(1)=1, a(2)=2, then for each
 *            subsequent row T(n,2j)=L(T(n‑1,j)), T(n,2j+1)=U(T(n‑1,j))
 * Range:     u8 n <= 64, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

seq_t a(idx_t n)
{
    /* Base cases */
    if (n == 1) return 1;
    if (n == 2) return 2;

    /* Static cache and state for memoisation */
    static bool initialized = false;
    static seq_t cache[20000];
    static idx_t cache_cnt = 0;

    static seq_t buf0[8192];
    static seq_t buf1[8192];
    static seq_t *cur = buf0;
    static seq_t *next = buf1;
    static idx_t cur_len = 0;

    if (!initialized) {
        /* initialise row 1 and cache */
        cur[0] = 2;            /* second row: T(1,0)=2 */
        cur_len = 1;

        cache[0] = 1;          /* a(1) */
        cache[1] = 2;          /* a(2) */
        cache_cnt = 2;

        initialized = true;
    }

    if (n <= cache_cnt) {
        return cache[n - 1];
    }

    /* Build rows until we have at least n terms */
    while (cache_cnt < n) {
        idx_t next_len = cur_len * 2;

        for (idx_t j = 0; j < cur_len; ++j) {
            seq_t val = cur[j];
            next[2 * j]     = (seq_t)3 * val - (seq_t)2;
            next[2 * j + 1] = ((seq_t)3 * val + (seq_t)1) / (seq_t)2;
        }

        for (idx_t j = 0; j < next_len; ++j) {
            cache[cache_cnt++] = next[j];
        }

        /* Prepare for next iteration */
        seq_t *tmp = cur;
        cur = next;
        next = tmp;
        cur_len = next_len;
    }

    return cache[n - 1];
}
